import { Request, Response } from 'express';
import { AssignTaskUseCase } from '../application/AssignTaskUseCase';
import { CreateTaskUseCase } from '../application/CreateTaskUseCase';
import { ListProjectTasksUseCase } from '../application/ListProjectTasksUseCase';
import { MarkTaskDoneUseCase } from '../application/MarkTaskDoneUseCase';
import { asString, bodyOf } from './requestValues';

export class TaskController {
  constructor(
    private readonly createTask: CreateTaskUseCase,
    private readonly listTasks: ListProjectTasksUseCase,
    private readonly assignTask: AssignTaskUseCase,
    private readonly markTaskDone: MarkTaskDoneUseCase,
  ) {}

  create = async (req: Request, res: Response): Promise<void> => {
    const body = bodyOf(req.body);
    const task = await this.createTask.execute({
      projectId: String(req.params.projectId),
      title: asString(body.title),
      description: asString(body.description),
      dueDate: asString(body.dueDate),
      status: asString(body.status),
      assigneeId: asString(body.assigneeId),
    });
    res.status(201).json(task);
  };

  list = async (req: Request, res: Response): Promise<void> => {
    const tasks = await this.listTasks.execute({
      projectId: String(req.params.projectId),
      status: asString(req.query.status),
      assigneeId: asString(req.query.assigneeId),
    });
    res.json(tasks);
  };

  assign = async (req: Request, res: Response): Promise<void> => {
    const task = await this.assignTask.execute({
      projectId: String(req.params.projectId),
      taskId: String(req.params.taskId),
      assigneeId: asString(bodyOf(req.body).assigneeId) ?? '',
    });
    res.json(task);
  };

  done = async (req: Request, res: Response): Promise<void> => {
    const task = await this.markTaskDone.execute({
      projectId: String(req.params.projectId),
      taskId: String(req.params.taskId),
    });
    res.json(task);
  };
}

